        sides = []
        if top: sides.append((r, 'up'))
        if bottom: sides.append((h-1-r, 'down'))
        if left: sides.append((c, 'left'))
        if right: sides.append((w-1-c, 'right'))
        if not sides:
            continue
        _, direction = min(sides)
        if direction == 'up':
            for rr in range(1, r): out[rr][c] = color
        elif direction == 'down':
            for rr in range(r+1, h-1): out[rr][c] = color
        elif direction == 'left':
            for cc in range(1, c): out[r][cc] = color
        else:
            for cc in range(c+1, w-1): out[r][cc] = color
